"""Runner for the scale_town06 scenario (N egos on Town06, generated by
scripts/ispass/gen_scale_town06.py).

Distributed (-d): this process is the orchestrator. It waits for the vehicle
clients to register, finds the N egos the index-0 client spawned (role names
hero, hero1, ...), builds the edge proxy, then ticks the world until
SCENARIO_MAX_STEP (default 200) and logs the wall time of every tick.
Sequential: the ScenarioRunner subprocess spawns the egos and this process runs
every vehicle and the edge manager itself.
"""
import asyncio
import os
import time
from multiprocessing import Process

import ecloud_pb2 as ecloud

import scenario_runner.scenario_runner as sr
import ecav.scenario_testing.utils.sim_api as sim_api
from ecav.core.common.cav_world import CavWorld
from ecav.scenario_testing.evaluations.evaluate_manager import EvaluationManager
from ecav.scenario_testing.utils.yaml_utils import add_current_time

MAX_STEP = int(os.environ.get("SCENARIO_MAX_STEP", 200))
SCENARIO_NAME = 'scale_town06'
TAG = "[SCALE_TOWN06]"


def exec_scenario_runner(scenario_params):
    runner = sr.ScenarioRunner(scenario_params.scenario_runner)
    runner.run()
    runner.destroy()


def run_vehicle(opt, scenario_params):
    """One distributed vehicle client: ScenarioRunner with this vehicle index."""
    assert opt.distributed, "Must run in distributed mode when specifying vehicle index"
    try:
        exec_scenario_runner(scenario_params)
    except Exception:
        print(f"vehicle_index: {scenario_params.scenario_runner.vehicle_index}")
        raise


def _role_index(role):
    if role == 'hero':
        return 0
    if role.startswith('hero') and role[4:].isdigit():
        return int(role[4:])
    return None


def _find_egos(world, n):
    """The egos in vehicle-index order, or None until all n exist."""
    egos = {}
    for v in world.get_actors().filter('vehicle.*'):
        k = _role_index(v.attributes.get('role_name', ''))
        if k is not None:
            egos[k] = v
    if len(egos) < n:
        return None
    return [egos[k] for k in range(n)]


def run_scenario(opt, scenario_params):
    cav_world = None
    scenario_manager = None
    eval_manager = None
    sr_process = None
    edge_list = []
    step = 0
    tick_ms = []
    try:
        scenario_params = add_current_time(scenario_params)
        if getattr(opt, 'output_dir', None):
            scenario_params['run_output_dir'] = opt.output_dir
        n_egos = len(scenario_params['scenario']['edge_list'][0]['vehicles'])

        cav_world = CavWorld(apply_ml=opt.apply_ml, config=scenario_params,
                             litserve=getattr(opt, 'litserve', False))
        scenario_manager = sim_api.ScenarioManager(
            scenario_params, opt.apply_ml, opt.version,
            town=scenario_params.scenario_runner.town,
            cav_world=cav_world, distributed=opt.distributed)

        t0 = time.time()
        if opt.distributed:
            asyncio.get_event_loop().run_until_complete(scenario_manager.run_comms())
        else:
            sr_process = Process(target=exec_scenario_runner, args=(scenario_params,))
            sr_process.start()
        world = scenario_manager.world

        egos = None
        while egos is None:
            egos = _find_egos(world, n_egos)
            if egos is None:
                print(f"{TAG} waiting for {n_egos} egos")
                time.sleep(2)
        print(f"{TAG} found {n_egos} egos after {time.time() - t0:.1f} s", flush=True)

        world_dt = scenario_params['world']['fixed_delta_seconds']
        edge_dt = scenario_params['edge_base']['edge_dt']
        edge_list = scenario_manager.create_edge_manager_from_scenario_runner(
            application=['edge'], edge_dt=edge_dt, world_dt=world_dt,
            ego_vehicle=egos, other_vehicles=[])
        print(f"{TAG} edge manager ready after {time.time() - t0:.1f} s", flush=True)

        eval_manager = EvaluationManager(
            scenario_manager.cav_world, script_name=SCENARIO_NAME,
            scenario_params=scenario_params,
            current_time=scenario_params['current_time'],
            output_dir=opt.output_dir)

        flag = True
        while flag:
            t_tick = time.time()
            if opt.distributed:
                command = ecloud.Command.PULL_OBJECTS_AND_TICK if step > 0 else ecloud.Command.TICK
                flag = scenario_manager.broadcast_message(command)
                t_bcast = time.time()
                scenario_manager.tick_world()
            else:
                scenario_manager.tick()
                t_bcast = time.time()
                for edge in edge_list:
                    edge.run_step(step)
            t_end = time.time()
            tick_ms.append((t_end - t_tick) * 1000.0)
            print(f"{TAG} tick {step} wall={(t_end - t_tick) * 1000:.0f}ms "
                  f"clients={(t_bcast - t_tick) * 1000:.0f}ms world={(t_end - t_bcast) * 1000:.0f}ms", flush=True)
            if opt.distributed and scenario_manager.all_vehicles_done:
                print(f"{TAG} all vehicles reported done, ending")
                break
            step += 1
            if step >= MAX_STEP:
                print(f"{TAG} reached the step limit {MAX_STEP}")
                break

    except SystemExit as e:
        print(f"Caught SystemExit({e.code}) in run_scenario - proceeding to evaluation/cleanup")
    except Exception as e:
        import traceback
        print(f"Caught exception {type(e).__name__} in run_scenario: {e} - proceeding to evaluation/cleanup")
        print(traceback.format_exc())
    finally:
        if tick_ms:
            s = sorted(tick_ms[5:] or tick_ms)
            print(f"{TAG} SUMMARY ticks={len(tick_ms)} mean={sum(s) / len(s):.1f}ms "
                  f"p50={s[len(s) // 2]:.1f}ms p99={s[min(len(s) - 1, int(len(s) * 0.99))]:.1f}ms "
                  f"(first 5 ticks excluded)", flush=True)
        if sr_process is not None:
            sr_process.terminate()
            sr_process.join(timeout=5)
        if opt.distributed and scenario_manager is not None:
            scenario_manager.end()
        if eval_manager is not None and os.environ.get("SCALE_SKIP_EVAL", "0") != "1":
            try:
                eval_manager.evaluate()
            except Exception as e:
                print(f"{TAG} evaluation failed: {type(e).__name__}: {e}")
        if cav_world is not None:
            cav_world.close()
        if scenario_manager is not None:
            scenario_manager.close()
